draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // red blood cell
  ctx.beginPath();
  ctx.arc(W / 2 + Math.sin(t) * 100, H / 2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'red';
  ctx.fill();

  // iron
  ctx.beginPath();
  ctx.arc(W / 2 + Math.sin(t) * 100, H / 2, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'gray';
  ctx.fill();

  // oxygen
  ctx.beginPath();
  ctx.arc(W / 2 + Math.cos(t) * 100, H / 2, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'blue';
  ctx.fill();

  // stick figure
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 + 100, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.fill();

  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 120);
  ctx.lineTo(W / 2, H / 2 + 150);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 130);
  ctx.lineTo(W / 2 - 20, H / 2 + 120);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 130);
  ctx.lineTo(W / 2 + 20, H / 2 + 120);
  ctx.stroke();

  ctx.restore();
}
